import rclpy
from rclpy.node import Node
from std_msgs.msg import Int32


class EchoNode(Node):

    def __init__(self):
        super().__init__('echo_node')
        self._pub = self.create_publisher(Int32, '/out', 10)
        self._sub = self.create_subscription(Int32, '/in', self._on_in, 10)

    def _on_in(self, msg):
        self._pub.publish(msg)


def main(args=None):
    rclpy.init(args=args)
    node = EchoNode()
    try:
        rclpy.spin(node)
    finally:
        node.destroy_node()
        rclpy.shutdown()


if __name__ == '__main__':
    main()

